// Employee.js (Frontend)
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import styled from 'styled-components';

// Styled Components...
// Same as in your initial code...

const EmployeePage = () => {
  const { registrationNumber } = useParams();
  const [employees, setEmployees] = useState([]);
  const [error, setError] = useState(null);
  const [newEmployee, setNewEmployee] = useState({
    name: '',
    role: '',
    phone: '',
    fixedSalary: '',
    daysWorked: '',
    expense: ''
  });
  const [showAddEmployeeForm, setShowAddEmployeeForm] = useState(false);

  useEffect(() => {
    if (!registrationNumber) {
      console.error('Registration Number is undefined.');
      setError('Registration Number is missing. Please check the URL.');
      return;
    }

    axios
      .get(`http://localhost:5001/api/employees/${registrationNumber}`)
      .then((response) => {
        setEmployees(response.data);
        setError(null);
      })
      .catch((error) => {
        console.error('Error fetching employee data:', error);
        setError('Failed to fetch employee data. Please try again later.');
      });
  }, [registrationNumber]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewEmployee((prevState) => ({
      ...prevState,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    axios
      .post(`http://localhost:5001/api/employees/${registrationNumber}`, newEmployee)
      .then((response) => {
        setEmployees((prev) => [...prev, response.data]);
        setShowAddEmployeeForm(false);
        setNewEmployee({
          name: '',
          role: '',
          phone: '',
          fixedSalary: '',
          daysWorked: '',
          expense: ''
        });
        setError(null);
      })
      .catch((error) => {
        console.error('Error adding employee:', error);
        setError('Failed to add employee. Please try again later.');
      });
  };

  const filterEmployeesByRole = (role) => {
    return employees.filter((employee) => employee.role === role);
  };

  if (error) {
    return <ErrorMessage>{error}</ErrorMessage>;
  }

  return (
    <Container>
      <Header>Employees for Lorry {registrationNumber}</Header>

      <Button onClick={() => setShowAddEmployeeForm(!showAddEmployeeForm)}>
        {showAddEmployeeForm ? 'Cancel' : 'Add Employee'}
      </Button>

      {showAddEmployeeForm && (
        <FormWrapper>
          <Title>Add New Employee</Title>
          <form onSubmit={handleSubmit}>
            <InputWrapper>
              <Label htmlFor="name">Name</Label>
              <Input
                type="text"
                id="name"
                name="name"
                value={newEmployee.name}
                onChange={handleInputChange}
                required
                placeholder="Enter employee name"
              />
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="role">Role</Label>
              <Select
                id="role"
                name="role"
                value={newEmployee.role || ''}
                onChange={handleInputChange}
                required
              >
                <option value="" disabled>
                  Select role
                </option>
                <option value="driver">Driver</option>
                <option value="driller">Driller</option>
                <option value="manager">Lorry Manager</option>
                <option value="worker">Worker</option>
              </Select>
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="phone">Phone Number</Label>
              <Input
                type="text"
                id="phone"
                name="phone"
                value={newEmployee.phone}
                onChange={handleInputChange}
                required
                placeholder="Enter phone number"
              />
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="fixedSalary">Fixed Salary</Label>
              <Input
                type="number"
                id="fixedSalary"
                name="fixedSalary"
                value={newEmployee.fixedSalary}
                onChange={handleInputChange}
                required
                placeholder="Enter fixed salary"
              />
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="daysWorked">Days Worked</Label>
              <Input
                type="number"
                id="daysWorked"
                name="daysWorked"
                value={newEmployee.daysWorked}
                onChange={handleInputChange}
                required
                placeholder="Enter number of days worked"
              />
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="expense">Expense</Label>
              <Input
                type="number"
                id="expense"
                name="expense"
                value={newEmployee.expense}
                onChange={handleInputChange}
                required
                placeholder="Enter total expense"
              />
            </InputWrapper>

            <Button type="submit">Add Employee</Button>
          </form>
        </FormWrapper>
      )}

      <EmployeeColumns>
        {/* Render employee cards */}
        {/* Same as in your initial code... */}
      </EmployeeColumns>
    </Container>
  );
};

export default EmployeePage;
